namespace SpriteKind {
    export const Coin = SpriteKind.create()
    export const Flower = SpriteKind.create()
}
function Start_Level () {
    if (current_level == 0) {
        tiles.setCurrentTilemap(tilemap`level1`)
    } else {
        tiles.setCurrentTilemap(tilemap`level2`)
    }
    tiles.placeOnRandomTile(Doggy, assets.tile`Spawn_Doggy`)
    for (let value of tiles.getTilesByType(assets.tile`Spawn_Doggy`)) {
        tiles.setTileAt(value, assets.tile`transparency16`)
    }
    Doggy.ay = 350
    scene.cameraFollowSprite(Doggy)
    info.setLife(5)
    for (let value of tiles.getTilesByType(assets.tile`Coin_Collectable`)) {
        Coin = sprites.create(assets.image`Coin_Actual`, SpriteKind.Coin)
        animation.runImageAnimation(
        Coin,
        assets.animation`Coin_Animation`,
        500,
        true
        )
        tiles.placeOnTile(Coin, value)
        tiles.setTileAt(value, assets.tile`transparency16`)
    }
    for (let value of tiles.getTilesByType(assets.tile`Flower_Placeholder`)) {
        Flower = sprites.create(assets.image`Flower_1`, SpriteKind.Flower)
        tiles.placeOnTile(Flower, value)
        tiles.setTileAt(value, assets.tile`transparency16`)
    }
}
sprites.onOverlap(SpriteKind.Player, SpriteKind.Coin, function (sprite, otherSprite) {
    info.changeScoreBy(1)
    sprites.destroy(otherSprite)
})
scene.onOverlapTile(SpriteKind.Player, assets.tile`myTile`, function (sprite, location) {
    current_level += 1
    Start_Level()
})
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (Doggy.vy == 0) {
        Doggy.vy = -150
    }
})
sprites.onOverlap(SpriteKind.Player, SpriteKind.Flower, function (sprite, otherSprite) {
    sprites.destroy(otherSprite)
    Bee = sprites.create(img`
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        . . . . . . . . . . . . . . . . 
        `, SpriteKind.Enemy)
    animation.runImageAnimation(
    Bee,
    assets.animation`Bee_EnemyAnamation`,
    100,
    true
    )
    Bee.setPosition(Doggy.x + 80, Doggy.y - 80)
    Bee.follow(Doggy)
})
scene.onOverlapTile(SpriteKind.Player, assets.tile`Lava`, function (sprite, location) {
    game.gameOver(false)
    game.setGameOverEffect(false, effects.melt)
})
sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite, otherSprite) {
    sprites.destroy(otherSprite)
    if (Doggy.y < otherSprite.y) {
        info.changeScoreBy(3)
    } else {
        info.changeLifeBy(-1)
    }
})
let Bee: Sprite = null
let Flower: Sprite = null
let Coin: Sprite = null
let Doggy: Sprite = null
let current_level = 0
scene.setBackgroundImage(assets.image`Sky_1`)
current_level = 1
Doggy = sprites.create(assets.image`Dog`, SpriteKind.Player)
controller.moveSprite(Doggy, 100, 0)
Start_Level()
game.onUpdate(function () {
    Doggy.setImage(assets.image`Dog`)
    if (Doggy.vy < 0) {
        Doggy.setImage(assets.image`Doggy_Jump`)
    } else if (Doggy.vy > 0) {
        Doggy.setImage(assets.image`Doggy_Fall`)
    } else {

    }
    if (Doggy.vx < 0) {
        Doggy.image.flipX()
    }
})

